import{_ as n,l as i,o as e,c as A,v as t,p as l,x as r,d as p,i as s,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"CAPM 用于项目贴现","description":"","frontmatter":{"title":"CAPM 用于项目贴现","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/capm-project-discount.md","filePath":"econ/capm-project-discount.md","lastUpdated":1789023840000}'),_={name:"econ/capm-project-discount.md"};function E(b,a,C,d,h,m){const o=i("Mermaid");return e(),A("div",null,[a[1]||(a[1]=t('<h1 id="capm-用于项目贴现" tabindex="-1">CAPM 用于项目贴现 <a class="header-anchor" href="#capm-用于项目贴现" aria-label="Permalink to &quot;CAPM 用于项目贴现&quot;">​</a></h1><div class="epigraph"><p>项目的资本成本取决于项目的风险，不是取决于公司碰巧怎样融资、也不是取决于公司股票过去的 beta。</p><footer>—— 据 Sharpe, Journal of Finance 1964；Brealey, Myers and Allen, Principles of Corporate Finance；Tirole, The Theory of Corporate Finance, 第 3 章 整理</footer></div><p><a href="/econ/wacc-cost-of-capital">上一课</a>把 WACC 的代数写清，但 \\(r_E\\) 与 \\(r_U\\) 仍是输入。本课缺口是用 <a href="/econ/capm-theory">CAPM 作为均衡陈述</a> 去填<strong>项目</strong>的要求回报：可比纯业务的资产 beta，而不是本公司股权 beta 一刀切。不重推切点组合，不把横截面异象与限价簿因子工程写进本栏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CAPM 说 \\(\\mathrm{E}[R_i]-r_f=\\beta_i(\\mathrm{E}[R_m]-r_f)\\)。公司金融进阶要的不是再证明市场组合有效，而是：贴现项目时，\\(i\\) 是项目，不是本公司股票。多元化的股东按不可分散风险要补偿；项目对市场的 beta 决定 \\(r_U\\)，再按目标杠杆lever 成 \\(r_E\\) 或直接进 WACC。用本公司历史股权 beta，等于假设新项目与现有资产同一风险、且杠杆恰好等于过去回归窗口里的杠杆。</p><p>缺口因此是拆两层：经营风险（资产 beta）对财务风险（杠杆把 \\(\\beta_E\\) 放大）。Tirole 把投资决策写成「NPV 在股东目标下用机会成本」；机会成本由项目风险定。Brealey–Myers 的纯业务可比（pure play）是操作：找业务相近、交易的企业，去杠杆得到 \\(\\beta_A\\)，再按项目目标杠杆杠杆回去。</p><p><span class="marginnote">Hamada 公式（在债务 beta 为零的近似下）：\\(\\beta_E=\\beta_A\\bigl(1+(1-\\tau_c)D/E\\bigr)\\)。债务有风险时 \\(\\beta_D\\gt 0\\)，去杠杆要同时拆 \\(\\beta_E\\) 与 \\(\\beta_D\\)。不要把权益 beta 直接当项目成本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>步骤：（1）选可比公司或分部，估计股权 beta；（2）用市值 \\(D\\)、\\(E\\) 与债务 beta（投资级可近似为零）得到资产 beta \\(\\beta_A=(E/V)\\beta_E+(D/V)\\beta_D\\)；（3）项目若风险与可比同类，用 \\(\\beta_A\\) 得 \\(r_U=r_f+\\beta_A\\times\\) 溢价；（4）若用 WACC，按<strong>项目</strong>目标 \\(D/V\\) 杠杆，不要按母公司。项目比公司更险（绿野、新兴市场需求），\\(\\beta_A\\) 应更高，即使母公司是公用事业。</p><p>公司 WACC 一刀切的后果：安全项目被过高的门槛拒绝，危险项目被过低的门槛接受——内部资本市场把风险项目当「便宜增长」。这与总部配额一样，是代理，不是 CAPM。</p>',10)),(e(),l(c,null,{default:r(()=>[s(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MKT%5B%22%E5%B8%82%E5%9C%BA%E6%BA%A2%E4%BB%B7%22%5D%20--%3E%20RU%5B%22rU%20%3D%20rf%20%2B%20%CE%B2A%20x%20%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20COMP%5B%22%E5%8F%AF%E6%AF%94%E7%BA%AF%E4%B8%9A%E5%8A%A1%22%5D%20--%3E%20BA%5B%22%E5%8E%BB%E6%9D%A0%E6%9D%86%20%CE%B2A%22%5D%0A%20%20BA%20--%3E%20RU%0A%20%20RU%20--%3E%20WACC%5B%22%E6%8C%89%E9%A1%B9%E7%9B%AE%E7%9B%AE%E6%A0%87%E6%9D%A0%E6%9D%86%E6%88%90%20WACC%22%5D%0A%20%20FIRM%5B%22%E6%9C%AC%E5%85%AC%E5%8F%B8%20%CE%B2E%22%5D%20--%3E%20WRONG%5B%22%E6%B7%B7%E5%85%A5%E6%97%A7%E4%B8%9A%E5%8A%A1%E4%B8%8E%E6%97%A7%E6%9D%A0%E6%9D%86%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>市场溢价用历史还是隐含，是输入争议，本课不裁判；对象是<strong>相对</strong>风险 \\(\\beta_A\\)。国家风险、项目特有的政治风险，若不能被股东分散，下一课之后的国家风险溢价再加；能分散的特有风险不进 CAPM 门槛。Tirole：可分散风险可以通过保险或股东组合处理，不应靠提高折现率假装已经处理——现金流里扣期望损失更干净。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是股东的边际定价，不是经理的感受波动。项目特有风险进入折现率，只当它进入 \\(\\mathrm{Cov}(\\cdot,R_m)\\) 或破坏税盾、诱发财务困境（那些走 APV 副作用或进 FCF，不走 beta）。经理厌恶自己的职业风险，会把特有波动写成「高门槛」；那是<a href="/econ/agency-free-cash-flow">代理</a>与风险厌恶经理，不是 CAPM。</p><p>与 MM 的衔接：贴现用 \\(r_U\\) 或 WACC，对应无杠杆或杠杆后的要求回报；不要用 \\(r_E\\) 去折未杠杆 FCF。项目融资若改变公司杠杆，WACC 的权重是项目的，APV 更干净。本课只钉：风险来自项目对市场的暴露。</p><h3 id="公司-beta-不是项目-beta" tabindex="-1">公司 beta 不是项目 beta <a class="header-anchor" href="#公司-beta-不是项目-beta" aria-label="Permalink to &quot;公司 beta 不是项目 beta&quot;">​</a></h3><p>并购一个低 beta 部门、再用母公司高 WACC 去折，会人为制造 NPV。反向：高 beta 项目挂在低 WACC 公司下，会通过。资本预算的代理成本常常藏在错误的折现率里，而不是 IRR 表上。</p><p><span class="marginnote">底线：CAPM 在本栏是项目机会成本的一张线性表。实证拒绝 CAPM 横截面，不取消「用可比资产风险、而不是用本公司历史股票」这一句操作纪律。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在本课重做 Sharpe–Lintner 的均衡推导，也不要把 Fama–French 因子当成已经进了公司 WACC——多因子是量化栏与资产定价续，本课停在单因子机会成本。项目与市场相关性低，不是「折现率用无风险」：若仍有不可分散的风险暴露，beta 可以小但不是自动为零；真正的特有灾难应进现金流情景。</p><p>后课默认：项目 \\(r_U\\) 来自纯业务 \\(\\beta_A\\)；杠杆按项目目标。公司 WACC 一刀切会选错风险项目。下一课：杠杆路径随时间变时，WACC 不够，改 APV。</p><p>不要把限价簿上的高频 beta、微观结构噪声写成项目成本。日频估计的公司 beta 不是资本预算对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>项目资本成本由项目 \\(\\beta_A\\) 决定，不是由本公司股票的历史 beta 决定。</li><li>纯业务去杠杆，再按项目目标杠杆；特有风险优先进现金流，不进门槛。</li><li>公司 WACC 一刀切会拒绝安全项目、放行危险项目。</li><li>出处：Sharpe 1964；Hamada；Brealey, Myers and Allen；Tirole, <em>Theory of Corporate Finance</em>。</li></ul>',13))])}const P=n(_,[["render",E]]);export{f as __pageData,P as default};
